import{_ as a}from"./chunks/3dots_menu.BrLPqWzo.js";import{_ as e,a as o,b as t,c as r,d as s,e as l}from"./chunks/3DM-BR-CB7.Bp-b42-4.js";import{_ as n}from"./chunks/BDM.scaBLLhv.js";import{_ as p}from"./chunks/DIS.DdpTdGGD.js";import{_ as c,o as d,c as u,a3 as m}from"./chunks/framework.g9mfNVRQ.js";const I=JSON.parse('{"title":"Reinstallazione","description":"","frontmatter":{"source_hash":"59290c3e55","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/troubleshoot/reinstall.md","filePath":"it/troubleshoot/reinstall.md"}'),b={name:"it/troubleshoot/reinstall.md"};function h(v,i,g,k,f,z){return d(),u("div",null,[...i[0]||(i[0]=[m('<h2 id="uninstall-xdrip" tabindex="-1">Disinstallare xDrip <a class="header-anchor" href="#uninstall-xdrip" aria-label="Permalink to &quot;Disinstallare xDrip {#uninstall-xdrip}&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Dati storici</p><p>Disinstallare xDrip rimuove anche tutti i dati e le impostazioni, senza possibilità di recupero.<br> Assicurati di fare prima un <strong><a href="#backup">backup</a></strong> del database e/o di tutte le impostazioni.<br> Si consiglia di caricare i dati su <a href="https://nightscout.github.io/" target="_blank" rel="noreferrer">Nightscout</a>.</p></div><br><p>Di solito non dovrebbe essere necessario, ma potresti dover disinstallare xDrip per risolvere un problema, o per passare a o da una versione fork. Puoi disinstallare xDrip come qualsiasi altra app Android, con una pressione prolungata sull&#39;icona oppure da Impostazioni Android -&gt; App.</p><h2 id="reinstall-xdrip" tabindex="-1">Reinstallare xDrip <a class="header-anchor" href="#reinstall-xdrip" aria-label="Permalink to &quot;Reinstallare xDrip {#reinstall-xdrip}&quot;">​</a></h2><p>Segui questa sequenza:</p><ol><li>Backup (in locale o nel cloud)</li><li>Disinstalla xDrip</li><li>Installa xDrip</li><li>Ripristino (dal backup locale o nel cloud)</li><li>Controlla tutte le impostazioni e ricrea i tuoi allarmi</li></ol><h2 id="backup" tabindex="-1">Backup <a class="header-anchor" href="#backup" aria-label="Permalink to &quot;Backup {#backup}&quot;">​</a></h2><p>Puoi fare il backup del database in locale oppure sul tuo <a href="#cloud-backup">Google Drive</a>.</p><h3 id="backup-the-database" tabindex="-1">Backup del database <a class="header-anchor" href="#backup-the-database" aria-label="Permalink to &quot;Backup del database {#backup-the-database}&quot;">​</a></h3><p>Il database contiene tutte le letture di glicemia, i trattamenti e le note. È vivamente consigliato fare il backup del database e conservarne una copia su un altro dispositivo se vuoi tenere i dati esistenti, e come precauzione in caso di perdita del telefono, guasto, ...<br> È vivamente consigliato anche il caricamento su <a href="https://nightscout.github.io/" target="_blank" rel="noreferrer">Nightscout</a>.</p><p>Esportare il database <a href="./../use/loadsavesettings.html#save-settings">salva anche le impostazioni</a>.</p><p>Dalla schermata principale di xDrip seleziona il menu a 3 puntini in alto a destra, Funzioni di importazione / esportazione, Esporta Database.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"></p><p> Funzioni di importazione / esportazione ►<br>  Esporta Database</p></div><br><p>Il database attuale viene salvato in <code>/storage/emulated/0/xdrip</code> o <code>Memoria interna/xdrip</code> Devi autorizzare xDrip ad accedere alla memoria del telefono.<br> Puoi fare tutti i backup che la memoria può contenere.</p><p>Se sei abbastanza veloce da toccare la scritta <code>SHARE</code> prima che scompaia, puoi usare le opzioni di condivisione del telefono per inviare il database a un altro dispositivo o copiarlo in un&#39;altra posizione.</p><img src="'+e+'" style="zoom:75%;"><p>Il backup si chiamerà <code>exportYYYYMMDD-HHMMSS.zip</code>, con <code>YYYY</code> l&#39;anno corrente, <code>MM</code> il mese, <code>DD</code> il giorno e <code>HHMMSS</code> per ore, minuti e secondi. Così puoi avere più backup, ciascuno identificato da un orario univoco.</p><p>Se vuoi conservarne una copia sicura, invia il file a te stesso per email, salvalo su un cloud o copialo via USB su un computer.</p><p>È un database SQLite che puoi consultare con diversi strumenti, come <a href="https://sqlitebrowser.org/" target="_blank" rel="noreferrer">SQLite Browser</a>.</p><br><h2 id="restore" tabindex="-1">Ripristino <a class="header-anchor" href="#restore" aria-label="Permalink to &quot;Ripristino {#restore}&quot;">​</a></h2><p>Puoi ripristinare il database da una copia locale oppure dal tuo <a href="#cloud-backup">Google Drive</a>.</p><h3 id="restore-settings" tabindex="-1">Ripristinare le impostazioni <a class="header-anchor" href="#restore-settings" aria-label="Permalink to &quot;Ripristinare le impostazioni {#restore-settings}&quot;">​</a></h3><p>Al termine dell&#39;installazione di xDrip, se è disponibile un backup, xDrip ti proporrà di ripristinarlo automaticamente.<br> Seleziona RIPRISTINARE LE IMPOSTAZIONI</p><div class="admonition xdripitem"><p class="admonition-title">Backup rilevato</p><p> Sembra che tu abbia un backup delle impostazioni, vuoi provare a ripristinarlo?</p><p> NO    <span style="background-color:white;color:black;"> RIPRISTINARE LE IMPOSTAZIONI </span></p></div><p>Se non vedi questo messaggio, <a href="./../use/loadsavesettings.html#load-settings">ripristinale manualmente</a>.</p><h3 id="restore-a-database" tabindex="-1">Ripristinare un database <a class="header-anchor" href="#restore-a-database" aria-label="Permalink to &quot;Ripristinare un database {#restore-a-database}&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">Perdita di dati</p><p>Ripristinare un database <strong>elimina tutti i dati attuali</strong>.<br> Ripristina un database con <strong>la stessa versione di xDrip usata per esportarlo</strong>.<br> Assicurati di fare il backup del database attuale prima di ripristinarne uno.</p></div><p>Al termine dell&#39;installazione di xDrip, se è disponibile un backup del database, xDrip potrebbe proporti di ripristinarlo automaticamente.</p><p>Assicurati che sia il database che vuoi ripristinare, poi seleziona RIPRISTINA.</p><div class="admonition xdripitem"><p class="admonition-title">Ripristinare il backup?</p><p> Ripristinare il file di backup: export20210328-085436.zip</p><p> NO    <span style="background-color:white;color:black;"> RIPRISTINA </span></p></div><p>xDrip confermerà che il database è stato ripristinato correttamente.</p><div class="admonition xdripitem"><p class="admonition-title">Import Result</p><p> Successfully imported database</p></div><p><em>Nota: per sicurezza, il database attuale viene prima esportato; lo troverai nell&#39;elenco con il nome <code>b4import</code> seguito dalla data e ora dell&#39;importazione. Così potrai recuperarlo se necessario.</em></p><br><p>Se vuoi ripristinare un backup specifico, dalla schermata principale di xDrip seleziona il menu a 3 puntini in alto a destra, Funzioni di importazione / esportazione, Ripristina database.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"></p><p> Funzioni di importazione / esportazione ►<br>  Ripristina database</p></div><p>Vengono mostrate le istruzioni. Non devi spostare il file di backup se non l&#39;hai trasferito da un altro dispositivo, e non devi decomprimerlo. Fai attenzione quando ripristini un database con una versione di xDrip diversa: si consiglia di installare la <a href="./../install/install.html#verify-which-version-is-installed">versione di xDrip</a> usata per l&#39;esportazione prima di importare, poi potrai aggiornare xDrip.</p><div class="admonition xdripitem"><p class="admonition-title">Restore Instructions</p><p> WARNING: Database restore is rarely necessary and may cause SEVERE DATA LOSS.</p><p>Protect your data by uploading to Nightscout or Tidepool.</p><p>When switching phones, importing settings (alerts, colors, etc.) is usually sufficient. Restoring the database is typically unnecessary unless you need short-term access to historical data (for example, before a medical visit).</p><p>Instructions:</p><p>- Place the database in the &#39;xdrip&#39; folder. If it doesn&#39;t exist, perform an export once to create it.</p><p>- Restart this restore routine.</p><p>- Select the correct database and follow the on-screen instructions.</p></div><p>Seleziona il database che vuoi importare; guarda la data e la dimensione (usa il file manager del telefono) per essere sicuro di scegliere quello giusto.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+n+'" style="zoom:75%;">Ripristina database</p><p>export20220129-184625.zip<br> export20220129-184615.zip<br> b4import20220129-194141.zip</p></div><p>Quando sei sicuro di ripristinare il backup corretto, <code>Ok</code></p><div class="admonition xdripitem"><p class="admonition-title">Confirm Import</p><p> Do you really want to import<br>  &#39;export20220129-184615.zip&#39;?<br>  This may negatively affect the data integrity of your system!</p><p> ANNULLA    <span style="background-color:white;color:black;"> OK </span></p></div><p>xDrip confermerà che il database è stato ripristinato correttamente.</p><div class="admonition xdripitem"><p class="admonition-title">Import Result</p><p> Successfully imported database</p></div><p>Se hai ripristinato il database sbagliato, ripeti semplicemente gli stessi passaggi e seleziona la versione <code>b4import</code> più recente per tornare indietro.</p><div class="info custom-block"><p class="custom-block-title">Android 11 e successivi</p><p>C&#39;è un problema con le versioni recenti di Android che ti costringe a ripristinare il database più volte (da 3 a 4) prima di vederne il contenuto completo.</p></div><br><h2 id="cloud-backup" tabindex="-1">Backup nel cloud <a class="header-anchor" href="#cloud-backup" aria-label="Permalink to &quot;Backup nel cloud {#cloud-backup}&quot;">​</a></h2><p>Il backup nel cloud ti permette di salvare sul tuo Google Drive un file compresso che contiene sia il database sia le impostazioni.<br> Per usare questa funzione devi aver effettuato l&#39;accesso al tuo account Google.</p><p>Seleziona Backup nel Cloud.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"></p><p> Funzioni di importazione / esportazione ►<br>  Backup nel Cloud</p></div><div class="admonition xdripitem"><p class="admonition-title">Backup nel Cloud</p><p>  Puoi utilizzare Google Drive per il backup<br>        Pronto</p></div><p>Per usare questa funzione devi prima selezionare una posizione di backup.</p><h3 id="select-backup-location" tabindex="-1">Selezionare la posizione di backup <a class="header-anchor" href="#select-backup-location" aria-label="Permalink to &quot;Selezionare la posizione di backup {#select-backup-location}&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title"><span style="background-color:white;color:black;"> Seleziona dove salvare il Backup </span></p></div><div class="admonition xdripitem"><p class="admonition-title">Scegli il file di backup</p><p>  Selezionare Automatico per permettere a xDrip di gestire i file nel Google Drive o selezionare un file alternativo per ripristinare da altrove.</p><p>       <span style="background-color:white;color:black;"> GESTISCI AUTOMATICAMENTE </span></p><p>        <span style="background-color:white;color:black;"> USA FILE ALTERNATIVO </span></p></div><ul><li>Usa File Alternativo ti permette di selezionare una cartella e un file di backup diversi durante il <strong>ripristino</strong>.</li><li>Quando fai il <strong>primo backup</strong>, o quando recuperi <strong>una reinstallazione di xDrip</strong> sullo stesso telefono, seleziona Gestisci Automaticamente.</li></ul><p>Devi autorizzare xDrip ad accedere al tuo account Google. xDrip salverà e recupererà solo il file di backup dal tuo Google Drive. <strong>Nient&#39;altro.</strong></p><img src="'+o+'" style="zoom:75%;"><p>Al termine, xDrip confermerà l&#39;accesso:</p><img src="'+t+'" style="zoom:75%;"><p>xDrip creerà una nuova cartella chiamata xDrip-Backups nella radice del tuo Google Drive.</p><img src="'+r+'" style="zoom:75%;"><h3 id="do-backup-now" tabindex="-1">Eseguire ora il backup <a class="header-anchor" href="#do-backup-now" aria-label="Permalink to &quot;Eseguire ora il backup {#do-backup-now}&quot;">​</a></h3><p>Una volta selezionata la posizione di backup, puoi eseguire un backup. Il file di backup verrà creato sul dispositivo e poi caricato sul tuo Google Drive.</p><div class="admonition xdrip"><p class="admonition-title"><span style="background-color:white;color:black;"> Esegui ora il backup </span></p></div><img src="'+s+'" style="zoom:75%;"><p>Puoi controllare lo stato del backup nel cloud nella parte alta della schermata.</p><img src="'+l+'" style="zoom:75%;"><p>Puoi far eseguire il backup nel cloud automaticamente ogni giorno.<br> Non attivarlo se hai un piano dati mobile limitato.</p><div class="admonition xdripitem"><p class="admonition-title"><img src="'+p+'" style="zoom:75%;"> Backup automatico giornaliero</p></div><h3 id="restore-from-backup" tabindex="-1">Ripristinare dal backup <a class="header-anchor" href="#restore-from-backup" aria-label="Permalink to &quot;Ripristinare dal backup {#restore-from-backup}&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title"><span style="background-color:white;color:black;"> Ripristino da Backup </span></p></div><div class="warning custom-block"><p class="custom-block-title">Perdita di dati</p><p>Ripristinare un database elimina tutti i dati attuali.<br> Ripristina un database con <strong>la stessa versione di xDrip usata per esportarlo</strong>.<br> Assicurati di fare il backup del database attuale prima di ripristinarne uno.</p></div><div class="admonition xdripitem"><p class="admonition-title">Sei davvero sicuro?</p><p> Il ripristino di un backup cancellerà le impostazioni e i dati correnti con quello dal backup.</p><p> Sei assolutamente sicuro di voler fare questo?</p><p> NO    <span style="background-color:white;color:black;"> SI </span></p></div><p>Il ripristino copia in locale il database dal cloud e sostituisce il database attuale.</p><p>Al termine, xDrip si riavvierà.</p><br><h2 id="new-phone-migration" tabindex="-1">Migrazione a un nuovo telefono <a class="header-anchor" href="#new-phone-migration" aria-label="Permalink to &quot;Migrazione a un nuovo telefono {#new-phone-migration}&quot;">​</a></h2><p>Esegui le operazioni seguenti:</p><p>Sul vecchio telefono:</p><ol><li><p><a href="#backup-the-database">Fai il backup del database in locale</a> o sul tuo <a href="#do-backup-now">Google Drive</a>.</p><ul><li>Se non userai il backup su Google cloud, invia a te stesso il backup del database o copialo su un computer.</li></ul></li><li><p>Se questo vecchio telefono è collegato a un sensore o a un bridge, assicurati di <a href="./../install/datasource.html#changing-data-source">disattivare la raccolta dati</a>, così non interferirà quando inizierai a usare il nuovo telefono.</p></li><li><p>Se questo vecchio telefono era master per dei follower xDrip Sync, <a href="./../use/sync.html#be-master-for-followers">togli il ruolo di master</a>.</p></li></ol><p>Sul nuovo telefono:</p><ol><li><p><a href="./../install/download.html#which-one-to-install">Installa</a> la <a href="./../install/install.html#verify-which-version-is-installed">stessa versione</a> di xDrip che usi sul vecchio telefono.</p><ul><li>Se non hai usato il backup su Google cloud:<br><a href="#backup-the-database">Fai il backup del database</a> (serve solo a creare le cartelle corrette).<br> Copia nella cartella giusta il file del database che ti sei inviato per mail o da un computer.</li></ul></li><li><p><a href="#restore-a-database">Ripristina il database dal backup locale</a> o dal tuo <a href="#restore-from-backup">Google Drive</a>.</p></li><li><p>Se il nuovo telefono è collegato a un sensore o a un bridge, <a href="./../install/datasource.html#sensor-selection">collegalo ora</a>. (La sorgente dati sarà corretta, ma dovrai ripristinare la connessione).</p></li></ol><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 23/11/2026</em></a></p>',89)])])}const R=c(b,[["render",h]]);export{I as __pageData,R as default};
